#include <bits/stdc++.h>
using namespace std;

int main() {
    int a[20] = {}, b[20] = {};
    int ans = INT_MAX;
    string c, d;
    cin >> c >> d;

    for (char ch : c) {
        a[ch - '0']++;
    }

    for (char ch : d) {
        if (ch == '9' || ch == '6') {
            b[6]++;
            b[9]++;
        } else if (ch == '2' || ch == '5') {
            b[2]++;
            b[5]++;
        } else {
            b[ch - '0']++;
        }
    }

    for (int i = 0; i < 10; i++) {
        if (a[i] > 0) {
            ans = min(ans, b[i] / a[i]);
        }
    }

    cout << (ans == INT_MAX ? 0 : ans) << '\n';
    return 0;
}

